  const { camera } = useThree();
  const isPlaying = useShowStore((s) => s.isPlaying);
  const ref = useRef({ t: 0 });

  useEffect(() => {
    let raf = 0;
    const tick = () => {
      if (isPlaying) {
        ref.current.t += 0.0006;
        const r = 48;
        camera.position.x = Math.sin(ref.current.t) * r;
        camera.position.z = Math.cos(ref.current.t) * r;
        camera.position.y = 18 + Math.sin(ref.current.t * 0.7) * 4;
        camera.lookAt(0, 8, 0);
      }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [camera, isPlaying]);

  return null;
}

